/* ===================================================================
   Matebase · glsl.js
   REFERENCIA DE GLSL. Lo que muestra el panel lateral al pulsar «GLSL»:
   los tipos, las palabras y las funciones del lenguaje de los shaders,
   tal como los acepta WebGL 1 (GLSL ES 1.00), que es lo que usan los
   visores del curso.

   Cada entrada:
     t   nombre, tal como se escribe (o una descripcion corta si p: true)
     g   grupo (uno de GLSL.grupos)
     s   firma o forma de uso (codigo GLSL, se colorea)
     d   explicacion (HTML y $latex$)
     e   ejemplo (codigo GLSL, se colorea)
     x   como compila el ejemplo tests.html: nada = dentro de mainImage,
         'global' = fuera de mainImage, 'solo' = es un shader entero,
         'no' = es un fragmento que no se sostiene solo
     v   variantes para la busqueda
     i   tema donde se explica
     p   true si el titulo es prosa y no codigo

   Criterios, los del glosario: frase entera, primero que ES y despues
   para que sirve. Y uno mas, propio de aqui: no documentar nada que no
   compile en WebGL 1. Lo que es de GLSL ES 3.00 va en su grupo, dicho.
   =================================================================== */
window.GLSL = {

intro: 'Referencia de <strong>GLSL ES 1.00</strong>, la versión de WebGL 1 que usan los visores ' +
  'del curso. <code>genType</code> quiere decir <code>float</code>, <code>vec2</code>, ' +
  '<code>vec3</code> o <code>vec4</code>: esas funciones actúan componente a componente.',

/* t: titulo del grupo; c: etiqueta corta, la que acompaña a cada entrada
   en los resultados de una busqueda, donde ya no se ve el grupo. */
grupos: [
  { id: 'tipos', t: 'Tipos', c: 'tipo' },
  { id: 'calif', t: 'Calificadores', c: 'calificador' },
  { id: 'control', t: 'Control de flujo', c: 'control' },
  { id: 'sintaxis', t: 'Construir, acceder y operar', c: 'sintaxis' },
  { id: 'trig', t: 'Trigonometría', c: 'trigonometría' },
  { id: 'exp', t: 'Potencias y exponenciales', c: 'exponencial' },
  { id: 'comunes', t: 'Funciones comunes', c: 'común' },
  { id: 'geom', t: 'Geometría', c: 'geometría' },
  { id: 'matriz', t: 'Matrices', c: 'matrices' },
  { id: 'logica', t: 'Comparar vectores', c: 'comparación' },
  { id: 'textura', t: 'Texturas', c: 'textura' },
  { id: 'deriv', t: 'Derivadas', c: 'derivada' },
  { id: 'integradas', t: 'Variables integradas', c: 'integrada' },
  { id: 'preproc', t: 'Preprocesador', c: 'preprocesador' },
  { id: 'visor', t: 'El visor del curso', c: 'visor del curso' },
  { id: 'recetas', t: 'Recetas del curso (no son del lenguaje)', c: 'receta del curso' },
  { id: 'es3', t: 'Lo que no hay en WebGL 1', c: 'no en WebGL 1' }
],

entradas: [

/* ---------------- tipos ---------------- */
{ t: 'float', g: 'tipos', s: 'float x = 1.0;',
  d: 'Número con decimales. Es el tipo de casi todo en un shader: coordenadas, distancias, colores. <strong>Un literal float lleva punto</strong>: <code>1.0</code>, no <code>1</code>. En WebGL 1 no hay conversión automática entre enteros y decimales, y <code>float x = 1;</code> no compila.',
  e: 'float r = 0.25;\nfloat borde = length(p) - r;', v: 'decimal numero real coma flotante punto', i: 'gfx-pixel' },
{ t: 'int', g: 'tipos', s: 'int i = 3;',
  d: 'Número entero. En WebGL 1 casi solo sirve para contar las vueltas de un bucle. No se mezcla con float sin convertir: <code>float(i)</code> e <code>int(x)</code>, que trunca hacia cero. No existen ni el operador <code>%</code> ni los operadores de bits: el resto se calcula con <code>mod</code> en floats.',
  e: 'float s = 0.0;\nfor (int j = 0; j < 5; j++) {\n    s += float(j);\n}', v: 'entero contador' },
{ t: 'bool', g: 'tipos', s: 'bool b = true;',
  d: 'Verdadero o falso. Es lo que devuelve una comparación y lo que piden <code>if</code> y el operador <code>?:</code>. Convertido a número, <code>float(b)</code> vale 1.0 o 0.0: la manera de usar una condición dentro de una cuenta.',
  e: 'bool dentro = d < 0.0;\nfloat m = float(dentro);', v: 'booleano verdadero falso condicion' },
{ t: 'vec2', g: 'tipos', s: 'vec2(x, y)\nvec2(a)',
  d: 'Pareja de floats: un punto o un vector del plano. <code>vec2(a)</code> pone las dos componentes iguales. Se lee con <code>.x</code> y <code>.y</code>, y la aritmética actúa componente a componente.',
  e: 'vec2 c = fragCoord / iResolution.xy;\nvec2 w = c - vec2(0.5);', v: 'vector punto plano pareja', i: 'gfx-coordenadas' },
{ t: 'vec3', g: 'tipos', s: 'vec3(r, g, b)\nvec3(a)\nvec3(vec2, float)',
  d: 'Tres floats: un color RGB, un punto o una dirección del espacio. Se construye con tres números, con uno solo (las tres componentes iguales, un gris) o combinando piezas. Sus componentes se llaman <code>.xyz</code> o <code>.rgb</code>, que son las mismas.',
  e: 'vec3 naranja = vec3(1.0, 0.5, 0.2);\nvec3 gris = vec3(0.3);\nvec3 punto = vec3(p, 0.0);', v: 'color rgb espacio punto 3d', i: 'gfx-color' },
{ t: 'vec4', g: 'tipos', s: 'vec4(vec3, float)\nvec4(vec2, float, float)',
  d: 'Cuatro floats. Es el tipo del color final, <code>rgba</code>, y de lo que devuelve <code>texture2D</code>. En el visor del curso la cuarta componente del color de salida se ignora: la pantalla es opaca.',
  e: 'vec4 salida = vec4(col, 1.0);\nvec4 prueba = vec4(uv, 0.0, 1.0);', v: 'rgba alfa cuatro componentes', i: 'gfx-pixel' },
{ t: 'ivec2 · ivec3 · ivec4', g: 'tipos', s: 'ivec2(vec2)',
  d: 'Vectores de enteros. En WebGL 1 se usan poco, porque casi toda la aritmética útil es con floats. <code>ivec2(fragCoord)</code> trunca cada componente.',
  e: 'ivec2 celda = ivec2(fragCoord);', v: 'vector entero' },
{ t: 'bvec2 · bvec3 · bvec4', g: 'tipos', s: 'bvec3 b = lessThan(a, c);',
  d: 'Vectores de booleanos. Los devuelven las comparaciones componente a componente, como <code>lessThan</code> o <code>equal</code>, y los resumen <code>any</code>, <code>all</code> y <code>not</code>.',
  e: 'bvec3 oscuros = lessThan(col, vec3(0.5));\nbool alguno = any(oscuros);', v: 'vector booleano' },
{ t: 'mat2', g: 'tipos', s: 'mat2(a, b, c, d)   // columnas (a, b) y (c, d)',
  d: 'Matriz 2×2. Se construye <strong>por columnas</strong>: <code>mat2(a, b, c, d)</code> tiene la primera columna $(a, b)$ y la segunda $(c, d)$. Por eso el giro se escribe <code>mat2(c, s, -s, c)</code>. <code>m * v</code> aplica la matriz; <code>v * m</code> aplica la traspuesta.',
  e: 'mat2 giro = mat2(cos(a), sin(a),\n                 -sin(a), cos(a));\np = giro * p;', v: 'matriz dos por dos columnas giro rotacion', i: 'gfx-matrices' },
{ t: 'mat3', g: 'tipos', s: 'mat3(vec3 col0, vec3 col1, vec3 col2)',
  d: 'Matriz 3×3, también por columnas. <code>mat3(r, u, f)</code> con tres <code>vec3</code> pone cada vector en una columna: así se escribe la base de una cámara y se gira la dirección de un rayo con un solo producto.',
  e: 'mat3 camara = mat3(r, u, f);\nvec3 dir = camara * normalize(vec3(p, 1.5));', v: 'matriz tres por tres base camara', i: 'gfx-camara' },
{ t: 'mat4', g: 'tipos', s: 'mat4(1.0)   // identidad',
  d: 'Matriz 4×4. Es la de las transformaciones con traslación de los motores 3D, en coordenadas homogéneas. En un fragment shader que lo calcula todo con fórmulas casi no aparece.',
  e: 'mat4 identidad = mat4(1.0);', v: 'matriz cuatro homogeneas proyeccion' },
{ t: 'sampler2D', g: 'tipos', s: 'uniform sampler2D tex;',
  d: 'Una textura 2D. Solo puede ser <code>uniform</code> o parámetro de una función, y solo sirve para leerla con <code>texture2D</code>. En el curso, <code>iChannel0</code> es un sampler2D.',
  e: 'vec3 leer(sampler2D tex, vec2 c)\n{\n    return texture2D(tex, c).rgb;\n}', x: 'global', v: 'textura imagen canal', i: 'gfx-buffers' },
{ t: 'samplerCube', g: 'tipos', s: 'uniform samplerCube cielo;',
  d: 'Una textura de cubo: seis imágenes que rodean al observador, leídas con una dirección 3D en lugar de un punto 2D. Se usa para cielos y reflejos precalculados. Los visores del curso no traen ninguna.',
  v: 'cubo cielo entorno reflejo' },
{ t: 'void', g: 'tipos', s: 'void f(...)',
  d: 'El tipo de una función que no devuelve nada. <code>mainImage</code> es <code>void</code>: entrega su resultado escribiendo en el parámetro <code>out vec4 color</code>.',
  e: 'void aclara(inout vec3 c)\n{\n    c = c / (1.0 + c);\n}', x: 'global', v: 'vacio sin valor' },
{ t: 'struct', g: 'tipos', s: 'struct Nombre { tipo campo; ... };',
  d: 'Agrupa varias variables bajo un tipo nuevo, con su constructor. Permite, por ejemplo, que una función devuelva a la vez la distancia a la escena y el material que se ha tocado.',
  e: 'struct Golpe { float dist; float material; };\nGolpe g = Golpe(1.5, 2.0);\nfloat dd = g.dist;', v: 'estructura registro campos' },

/* ---------------- calificadores ---------------- */
{ t: 'const', g: 'calif', s: 'const tipo NOMBRE = valor;',
  d: 'Constante de compilación: su valor se fija al escribirla y no se puede cambiar. Es lo que exigen los límites de los bucles en WebGL 1.',
  e: 'const int PASOS = 64;\nfor (int j = 0; j < PASOS; j++) {\n    t += 0.01;\n}', v: 'constante' },
{ t: 'uniform', g: 'calif', s: 'uniform float nombre;',
  d: 'Un valor que llega de fuera y es igual para todos los píxeles de un fotograma: la resolución, el tiempo, el ratón. Los deslizadores de los visores del curso son uniforms <code>float</code> que el preámbulo declara solo, con el nombre con que aparecen en el código.',
  e: 'uniform float grosor;', x: 'global', v: 'uniforme parametro externo mando deslizador' },
{ t: 'attribute · varying', g: 'calif', s: 'attribute vec2 posicion;   // en el vertex shader\nvarying vec2 vUv;          // del vertice al fragmento',
  d: 'Las dos maneras de pasar datos por el cauce gráfico en WebGL 1: <code>attribute</code> es un dato de cada vértice, que llega al vertex shader, y <code>varying</code> es lo que el vertex shader le deja al fragment shader, interpolado entre vértices. En los visores del curso el vértice es fijo y no hacen falta.',
  v: 'vertice interpolar cauce pipeline' },
{ t: 'in · out · inout', g: 'calif', s: 'void f(in float a, out float b, inout float c)',
  d: 'Calificadores de los parámetros de una función. <code>in</code>, el de siempre, es una copia de entrada; <code>out</code> es un valor que la función escribe y quien la llama recibe; <code>inout</code> es las dos cosas. <code>mainImage</code> recibe <code>in vec2 fragCoord</code> y devuelve el color en <code>out vec4 color</code>.',
  e: 'void polares(in vec2 q, out float radio, out float ang)\n{\n    radio = length(q);\n    ang = atan(q.y, q.x);\n}', x: 'global', v: 'parametro entrada salida referencia' },
{ t: 'precision · highp · mediump · lowp', g: 'calif', s: 'precision highp float;',
  d: 'La precisión con la que se guardan los números. <code>highp</code> es la de 32 bits; <code>mediump</code> puede tener mucha menos en un móvil, y entonces un <code>hash</code> con senos grandes o una coordenada lejana dejan de funcionar. El preámbulo del curso pone <code>precision highp float;</code>.',
  e: 'precision highp float;', x: 'global', v: 'precision bits movil' },
{ t: 'invariant', g: 'calif', s: 'invariant gl_Position;',
  d: 'Pide que una salida del vertex shader dé exactamente el mismo resultado en dos programas que hacen la misma cuenta, para que dos pasadas de un motor no parpadeen al coincidir. En un fragment shader suelto no se usa.',
  v: 'invariante parpadeo z fighting' },

/* ---------------- control de flujo ---------------- */
{ t: 'if · else', g: 'control', s: 'if (condicion) { ... } else { ... }',
  d: 'Bifurcación. Funciona, pero cada píxel puede tomar un camino distinto y la tarjeta gráfica rinde mejor si todos hacen lo mismo; por eso muchas decisiones se escriben con <code>step</code>, <code>mix</code>, <code>min</code> y <code>max</code>. Un <code>if</code> que depende de un uniform, o que se ahorra trabajo caro, sí compensa.',
  e: 'if (d < 0.0) {\n    col = vec3(1.0);\n} else {\n    col = vec3(0.0);\n}', v: 'si condicional bifurcar decidir', i: 'gfx-decidir' },
{ t: 'for', g: 'control', s: 'for (int i = 0; i < CONSTANTE; i++) { ... }',
  d: 'El único bucle de WebGL 1. El límite tiene que ser una <strong>constante</strong> y el índice no se puede tocar dentro: <code>i &lt; 64</code> sí, <code>i &lt; int(iTime)</code> no. Para salir antes se usa <code>break</code>. Así el compilador sabe cuántas vueltas puede dar como mucho.',
  e: 'float t = 0.0;\nfor (int j = 0; j < 80; j++) {\n    float dist = mapa(ro + t * rd);\n    if (dist < 0.001) break;\n    t += dist;\n}', v: 'bucle repetir iterar vueltas', i: 'gfx-raymarching' },
{ t: 'while · do', g: 'control', s: 'while (condicion) { ... }   // no compila en WebGL 1',
  d: 'Existen en la gramática de GLSL, pero <strong>WebGL 1 no los admite</strong>: el compilador responde «This type of loop is not allowed». Se reescriben como un <code>for</code> con límite constante y un <code>break</code>.',
  e: '// en vez de: while (x < 1.0) x += 0.01;\nfor (int j = 0; j < 200; j++) {\n    if (x >= 1.0) break;\n    x += 0.01;\n}', v: 'bucle mientras hacer' },
{ t: 'break · continue', g: 'control', s: 'break;\ncontinue;',
  d: '<code>break</code> sale del bucle en el que está; <code>continue</code> salta directamente a la vuelta siguiente. Con <code>break</code> se para el raymarching al tocar la superficie, o la iteración de un fractal cuando el punto escapa.',
  e: 'vec2 zz = vec2(0.0);\nfor (int j = 0; j < 64; j++) {\n    zz = vec2(zz.x * zz.x - zz.y * zz.y, 2.0 * zz.x * zz.y) + p;\n    if (dot(zz, zz) > 4.0) break;\n}', v: 'salir saltar interrumpir', i: 'gfx-fractales' },
{ t: 'return', g: 'control', s: 'return valor;',
  d: 'Termina una función y entrega su valor. En <code>mainImage</code>, que es <code>void</code>, un <code>return;</code> a secas acaba el píxel con el color que ya se haya escrito.',
  e: 'float cuadrado(float y)\n{\n    return y * y;\n}', x: 'global', v: 'devolver volver' },
{ t: 'discard', g: 'control', s: 'discard;',
  d: 'Abandona el píxel sin escribir nada, y se queda lo que hubiera detrás. Solo existe en el fragment shader. En el visor del curso lo que hay detrás es negro.',
  e: 'if (any(greaterThan(abs(p), vec2(0.45)))) discard;', v: 'descartar pixel' },
{ t: 'true · false', g: 'control', s: 'bool b = true;',
  d: 'Los dos valores de <code>bool</code>. <code>float(true)</code> vale 1.0 y <code>float(false)</code>, 0.0.',
  v: 'verdadero falso' },

/* ---------------- construir, acceder y operar ---------------- */
{ t: 'Constructores', p: true, g: 'sintaxis', s: 'vec3(float)\nvec3(float, float, float)\nvec4(vec3, float)\nfloat(int) · int(float) · float(bool)',
  d: 'Con el nombre del tipo se construye un valor y se convierte entre tipos. Un solo número rellena todas las componentes: <code>vec3(0.5)</code> es un gris. Se pueden encadenar piezas mientras sumen las componentes necesarias, como <code>vec4(uv, 0.0, 1.0)</code>. No hay conversión implícita: se escribe <code>float(i)</code>.',
  e: 'vec4 c4 = vec4(uv, 0.0, 1.0);\nfloat fr = float(3) / 8.0;', v: 'constructor conversion convertir cast tipo' },
{ t: '.xyzw · .rgba · .stpq', g: 'sintaxis', s: 'v.x   v.rgb   p.yx   c.bgr',
  d: 'Los nombres de las componentes de un vector: <code>.x .y .z .w</code>, o <code>.r .g .b .a</code> para colores, o <code>.s .t .p .q</code> para texturas. Son la misma memoria con tres nombres. Se pueden coger varias a la vez y en cualquier orden, <code>p.yx</code> o <code>v.xxy</code>, y a eso se le llama <em>swizzle</em>. No se mezclan juegos (<code>c.xg</code> no compila), y al escribir en un swizzle no se puede repetir componente.',
  e: 'vec2 girado = p.yx;\nvec3 e = vec3(0.002, 0.0, 0.0);\nvec3 ejeY = e.yxy;   // (0, 0.002, 0)', v: 'swizzle componentes x y z w r g b a s t p q' },
{ t: 'Índices [ ]', p: true, g: 'sintaxis', s: 'v[0]   m[1]   m[1][0]\nfloat a[4];',
  d: 'Acceso por posición: <code>v[0]</code> es <code>v.x</code>, y en una matriz <code>m[1]</code> es la <strong>segunda columna</strong> y <code>m[1][0]</code> su primera componente. Se pueden declarar arrays, <code>float a[4];</code>, pero en WebGL 1 no se inicializan al declararlos: se rellenan elemento a elemento.',
  e: 'float pesos[3];\npesos[0] = 0.25;\npesos[1] = 0.5;\npesos[2] = 0.25;', v: 'array vector indice corchetes columna lista' },
{ t: 'Operadores + − * /', p: true, g: 'sintaxis', s: 'vec3 * vec3   // componente a componente\nfloat * vec3  // cada componente\nmat2 * vec2   // producto matricial',
  d: 'Entre vectores del mismo tamaño actúan componente a componente: <code>vec3 * vec3</code> multiplica rojo por rojo y verde por verde. Un float con un vector opera con cada componente. La excepción son las matrices, con el producto del álgebra lineal. Los dos operandos tienen que ser del mismo tipo base: <code>2 * 1.5</code> no compila.',
  e: 'vec3 tintado = base * vec3(1.0, 0.9, 0.8);\nvec2 centrado = 2.0 * uv - 1.0;', v: 'suma resta producto division componente aritmetica' },
{ t: '< > == != && || ! ?:', g: 'sintaxis', s: 'a < b   a == b   b1 && b2   c ? x : y',
  d: 'Las comparaciones <code>&lt; &gt; &lt;= &gt;=</code> solo valen entre escalares; para vectores están <code>lessThan</code> y compañía. <code>==</code> y <code>!=</code> sí comparan vectores enteros. <code>&amp;&amp;</code>, <code>||</code> y <code>!</code> combinan bools, y <code>c ? a : b</code> elige un valor sin escribir un <code>if</code>.',
  e: 'float lado = p.x > 0.0 ? 1.0 : -1.0;\nbool arriba = p.y > 0.0 && p.x < 0.3;', v: 'comparacion logico ternario and or not menor mayor igual' },
{ t: 'Palabras reservadas', p: true, g: 'sintaxis', s: 'union  input  output  class  half  fixed  long  short\ndouble  unsigned  interface  static  public  inline  flat',
  d: 'GLSL guarda para el futuro palabras que todavía no usa, y no se pueden poner de nombre a una variable. Las que más sorprenden: <code>union</code>, <code>input</code>, <code>output</code>, <code>class</code>, <code>half</code>, <code>fixed</code>, <code>long</code>, <code>short</code>, <code>double</code>, <code>flat</code> e <code>interface</code>. Tampoco valen los nombres que empiezan por <code>gl_</code> ni los que llevan dos guiones bajos seguidos. Escribir los nombres en castellano esquiva casi todas.',
  e: 'float juntas = 1.0;   // «union» no compila\nfloat entrada = 0.5;  // «input» tampoco', v: 'reservada palabra clave nombre prohibido identificador error de sintaxis' },

/* ---------------- trigonometria ---------------- */
{ t: 'radians · degrees', g: 'trig', s: 'genType radians(genType grados)\ngenType degrees(genType radianes)',
  d: 'Pasan de grados a radianes y al revés: <code>radians(x)</code> es $x\\cdot\\frac{\\pi}{180}$. Todas las funciones trigonométricas trabajan en radianes.',
  e: 'float ang = radians(30.0);   // 0.5236', v: 'grados radianes convertir angulo' },
{ t: 'sin · cos', g: 'trig', s: 'genType sin(genType angulo)\ngenType cos(genType angulo)',
  d: 'Seno y coseno, con el ángulo en radianes. Valen entre −1 y 1 y se repiten cada $2\\pi$; <code>0.5 + 0.5 * sin(t)</code> oscila entre 0 y 1. Son el origen de casi todo movimiento periódico en un shader.',
  e: 'float onda = 0.5 + 0.5 * sin(TAU * p.x - 3.0 * iTime);', v: 'seno coseno sen periodico onda', i: 'gfx-tiempo' },
{ t: 'tan', g: 'trig', s: 'genType tan(genType angulo)',
  d: 'Tangente, en radianes. Se va a infinito al acercarse a $\\frac{\\pi}{2}$. En una cámara aparece al pasar del campo de visión a la distancia focal.',
  e: 'float foco = 0.5 / tan(radians(60.0) * 0.5);', v: 'tangente campo de vision', i: 'gfx-camara' },
{ t: 'asin · acos', g: 'trig', s: 'genType asin(genType x)\ngenType acos(genType x)',
  d: 'Arcoseno y arcocoseno: el ángulo cuyo seno o coseno vale $x$. Solo están definidos con <code>-1 ≤ x ≤ 1</code>, y un producto escalar de dos vectores unitarios puede pasarse de 1 por redondeo; por eso se protege con <code>clamp</code>.',
  e: 'float entre = acos(clamp(dot(f, u), -1.0, 1.0));', v: 'arcoseno arcocoseno angulo inverso' },
{ t: 'atan', g: 'trig', s: 'genType atan(genType y, genType x)\ngenType atan(genType y_sobre_x)',
  d: 'Arcotangente. Con <strong>dos argumentos</strong> devuelve el ángulo del punto $(x, y)$ entre $-\\pi$ y $\\pi$, distinguiendo los cuatro cuadrantes: es el ángulo polar. Ojo al orden, primero la <code>y</code>. Con un solo argumento da un ángulo entre $-\\frac{\\pi}{2}$ y $\\frac{\\pi}{2}$ y confunde cuadrantes opuestos. En $(0, 0)$ no está definida.',
  e: 'float ang = atan(p.y, p.x);     // de -PI a PI\nfloat vuelta = ang / TAU + 0.5;  // de 0 a 1', v: 'arcotangente angulo polar atan2', i: 'gfx-coordenadas' },
{ t: 'sinh · cosh · tanh', g: 'trig', s: '// no existen en WebGL 1',
  d: 'Funciones hiperbólicas. <strong>No existen en WebGL 1</strong>: llegaron con GLSL ES 3.00. Se escriben con exponenciales, $\\sinh x = \\frac{e^x - e^{-x}}{2}$.',
  e: 'float sh = 0.5 * (exp(x) - exp(-x));\nfloat ch = 0.5 * (exp(x) + exp(-x));\nfloat th = sh / ch;', v: 'hiperbolico seno hiperbolico coseno hiperbolico' },

/* ---------------- potencias y exponenciales ---------------- */
{ t: 'pow', g: 'exp', s: 'genType pow(genType x, genType y)',
  d: '$x^y$. <strong>No está definido si <code>x &lt; 0</code></strong>, ni si <code>x = 0</code> con <code>y ≤ 0</code>: <code>pow(-2.0, 2.0)</code> puede dar 4, 0 o un valor inválido según la tarjeta. Si la base puede ser negativa se usa <code>x * x</code> o <code>pow(abs(x), y)</code>. Con exponentes enteros pequeños, multiplicar es más rápido.',
  e: 'vec3 lineal = pow(col, vec3(2.2));\nfloat brillo = pow(max(dot(n, mitad), 0.0), 32.0);', v: 'potencia exponente gamma elevar', i: 'gfx-color' },
{ t: 'exp', g: 'exp', s: 'genType exp(genType x)',
  d: '$e^x$. Con exponente negativo es un decaimiento: <code>exp(-k * t)</code> vale 1 en $t = 0$ y se acerca a 0. Así se hacen la niebla, las estelas y los brillos que se apagan con la distancia.',
  e: 'col = mix(cielo, col, exp(-0.02 * t * t));', v: 'exponencial decaimiento niebla e', i: 'gfx-luz' },
{ t: 'log', g: 'exp', s: 'genType log(genType x)',
  d: 'Logaritmo neperiano, definido solo con <code>x &gt; 0</code>. Deshace una exponencial, y aparece en la distancia del disco de Poincaré.',
  e: 'float dh = log((1.0 + x) / (1.0 - x));', v: 'logaritmo neperiano ln', i: 'gfx-hiperbolico' },
{ t: 'exp2 · log2', g: 'exp', s: 'genType exp2(genType x)\ngenType log2(genType x)',
  d: '$2^x$ y el logaritmo en base 2. <code>log2</code> sirve para contar octavas o niveles de zoom: cada vez que una escala se duplica, sube uno.',
  e: 'float nivel = log2(8.0);   // 3.0', v: 'potencia de dos logaritmo base dos octava' },
{ t: 'sqrt', g: 'exp', s: 'genType sqrt(genType x)',
  d: 'Raíz cuadrada, no definida con <code>x &lt; 0</code>. Si se puede, se evita: comparar distancias al cuadrado con <code>dot(p, p)</code> se ahorra la raíz. En el trazado de rayos, la raíz del discriminante da el punto donde el rayo choca.',
  e: 'float disc = b * b - c;\nif (disc > 0.0) t = -b - sqrt(disc);', v: 'raiz cuadrada discriminante', i: 'gfx-trazado' },
{ t: 'inversesqrt', g: 'exp', s: 'genType inversesqrt(genType x)',
  d: '$\\frac{1}{\\sqrt{x}}$, definida con <code>x &gt; 0</code>. Es lo que hay dentro de <code>normalize</code>: <code>v * inversesqrt(dot(v, v))</code>.',
  e: 'vec2 unit = p * inversesqrt(dot(p, p));', v: 'inversa de la raiz' },

/* ---------------- comunes ---------------- */
{ t: 'abs', g: 'comunes', s: 'genType abs(genType x)',
  d: 'Valor absoluto. En un shader es un <strong>espejo</strong>: <code>p.x = abs(p.x)</code> hace que la mitad izquierda repita lo que se dibuja en la derecha. Aplicado a una distancia, <code>abs(d) - w</code> convierte una figura rellena en su contorno.',
  e: 'p = abs(p);   // simetria en los dos ejes\nfloat anillo = abs(length(p) - 0.3) - 0.02;', v: 'valor absoluto espejo simetria contorno', i: 'gfx-simetria' },
{ t: 'sign', g: 'comunes', s: 'genType sign(genType x)',
  d: 'Vale −1, 0 o 1 según el signo. Sirve para recordar de qué lado de un espejo estaba un punto antes de aplicarle <code>abs</code>.',
  e: 'float lado = sign(p.x);\np.x = abs(p.x);', v: 'signo' },
{ t: 'floor', g: 'comunes', s: 'genType floor(genType x)',
  d: 'El entero más cercano por debajo: <code>floor(2.7)</code> es 2.0 y <code>floor(-2.3)</code> es −3.0, que no es lo mismo que quitar los decimales. Devuelve un float. Al repetir el espacio da el <strong>número de celda</strong>. En WebGL 1 no existe <code>round</code>: se escribe <code>floor(x + 0.5)</code>.',
  e: 'vec2 celda = floor(p * 8.0);\nfloat redondo = floor(x + 0.5);', v: 'suelo parte entera redondear round celda', i: 'gfx-repetir' },
{ t: 'ceil', g: 'comunes', s: 'genType ceil(genType x)',
  d: 'El entero más cercano por encima: <code>ceil(2.1)</code> es 3.0 y <code>ceil(-2.7)</code> es −2.0.',
  e: 'float arriba = ceil(x * 4.0) / 4.0;', v: 'techo redondear hacia arriba' },
{ t: 'fract', g: 'comunes', s: 'genType fract(genType x)',
  d: 'La parte decimal, $x - \\lfloor x \\rfloor$: siempre entre 0 y 1, también con negativos (<code>fract(-0.25)</code> es 0.75). Es la operación que <strong>repite el espacio</strong>: <code>fract(p * 8.0)</code> da la posición dentro de cada celda.',
  e: 'vec2 local = fract(p * 8.0) - 0.5;   // de -0.5 a 0.5', v: 'parte decimal repetir celda local', i: 'gfx-repetir' },
{ t: 'mod', g: 'comunes', s: 'genType mod(genType x, float y)\ngenType mod(genType x, genType y)',
  d: '$x - y\\lfloor x/y \\rfloor$: el resto con el signo del divisor, así que <code>mod(-1.0, 3.0)</code> es 2.0 (en C, <code>-1 % 3</code> da −1). Repite el espacio con periodo $y$, y sustituye al operador <code>%</code>, que en WebGL 1 no existe.',
  e: 'vec3 rep = vec3(1.0, 0.5, 3.0);\nrep.xz = mod(rep.xz + 2.0, 4.0) - 2.0;', v: 'modulo resto periodico repetir', i: 'gfx-repetir' },
{ t: 'min · max', g: 'comunes', s: 'genType min(genType x, genType y)\ngenType max(genType x, genType y)',
  d: 'El menor y el mayor, componente a componente. Con distancias con signo son <strong>operaciones de conjuntos</strong>: <code>min(a, b)</code> es la unión de dos figuras, <code>max(a, b)</code> su intersección y <code>max(a, -b)</code> quita B de A.',
  e: 'float juntas = min(circulo, caja);\nfloat hueco = max(caja, -circulo);', v: 'minimo maximo union interseccion diferencia', i: 'gfx-decidir' },
{ t: 'clamp', g: 'comunes', s: 'genType clamp(genType x, genType lo, genType hi)',
  d: 'Encierra $x$ en el intervalo $[lo, hi]$: es <code>min(max(x, lo), hi)</code>, y no está definido si <code>lo &gt; hi</code>. Se usa para no salirse del rango antes de un <code>acos</code> o un <code>sqrt</code>, o antes de mostrar un color.',
  e: 'col = clamp(col, 0.0, 1.0);\nfloat hh = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);', v: 'recortar limitar saturar intervalo', i: 'gfx-decidir' },
{ t: 'mix', g: 'comunes', s: 'genType mix(genType a, genType b, float t)\ngenType mix(genType a, genType b, genType t)',
  d: 'Interpolación lineal: $a(1 - t) + b\\,t$. Con $t = 0$ da $a$, con $t = 1$ da $b$, y entre medias recorre el segmento. Con una máscara de 0 a 1 como $t$, <strong>pinta una capa encima de otra</strong>. Fuera de $[0, 1]$ extrapola.',
  e: 'col = mix(fondo, tinta, mascara);', v: 'interpolar lerp mezclar capa mascara', i: 'gfx-decidir' },
{ t: 'step', g: 'comunes', s: 'genType step(genType borde, genType x)\ngenType step(float borde, genType x)',
  d: 'Vale 0 si <code>x &lt; borde</code> y 1 si no: un escalón, un <code>if</code> escrito como número. <strong>Ojo al orden</strong>, primero el borde y después el valor. <code>step(d, 0.0)</code> vale 1 dentro de una figura y 0 fuera, con el borde dentado.',
  e: 'float dentro = step(d, 0.0);\nfloat derecha = step(0.5, uv.x);', v: 'escalon umbral heaviside borde', i: 'gfx-distancia' },
{ t: 'smoothstep', g: 'comunes', s: 'genType smoothstep(genType e0, genType e1, genType x)\ngenType smoothstep(float e0, float e1, genType x)',
  d: 'Un escalón suave: 0 antes de <code>e0</code>, 1 después de <code>e1</code>, y entre medias la curva $t^2(3 - 2t)$ con $t = \\frac{x - e_0}{e_1 - e_0}$ recortado a $[0, 1]$. Da bordes sin dientes y animaciones que arrancan y frenan. La especificación no define el caso <code>e0 ≥ e1</code>: para invertirlo se escribe <code>1.0 - smoothstep(e0, e1, x)</code>.',
  e: 'float relleno = 1.0 - smoothstep(0.0, 0.01, d);', v: 'escalon suave hermite antialiasing borde suave', i: 'gfx-distancia' },

/* ---------------- geometria ---------------- */
{ t: 'length', g: 'geom', s: 'float length(genType v)',
  d: 'El módulo de un vector, $\\sqrt{x^2 + y^2 + \\dots}$. <code>length(p - c)</code> es la distancia de <code>p</code> a <code>c</code>, y <code>length(p) - r</code> la distancia con signo a una circunferencia de radio $r$.',
  e: 'float disco = length(p - vec2(0.2, 0.0)) - 0.3;', v: 'modulo norma longitud distancia', i: 'gfx-distancia' },
{ t: 'distance', g: 'geom', s: 'float distance(genType a, genType b)',
  d: 'La distancia entre dos puntos: lo mismo que <code>length(a - b)</code>.',
  e: 'float dc = distance(p, vec2(0.0));', v: 'distancia entre puntos', i: 'gfx-distancia' },
{ t: 'dot', g: 'geom', s: 'float dot(genType a, genType b)',
  d: 'Producto escalar, $a_x b_x + a_y b_y + \\dots$ Con vectores unitarios es el coseno del ángulo que forman, y <code>max(dot(n, luz), 0.0)</code> es la luz difusa. <code>dot(v, v)</code> es el módulo al cuadrado, sin raíz.',
  e: 'float difusa = max(dot(n, luz), 0.0);', v: 'producto escalar coseno lambert difusa', i: 'gfx-luz' },
{ t: 'cross', g: 'geom', s: 'vec3 cross(vec3 a, vec3 b)',
  d: 'Producto vectorial: un vector perpendicular a los dos, con módulo el área del paralelogramo que forman. Solo existe para <code>vec3</code>, y el orden importa: <code>cross(b, a)</code> es <code>-cross(a, b)</code>. Con él se construye la base de una cámara.',
  e: 'vec3 der = normalize(cross(vec3(0.0, 1.0, 0.0), f));\nvec3 arr = cross(f, der);', v: 'producto vectorial perpendicular normal base', i: 'gfx-camara' },
{ t: 'normalize', g: 'geom', s: 'genType normalize(genType v)',
  d: 'El vector con la misma dirección y módulo 1, $v/|v|$. No está definido para el vector cero. Las direcciones de los rayos y las normales se normalizan siempre, porque <code>dot</code> solo es un coseno entre vectores unitarios.',
  e: 'vec3 dir = normalize(vec3(p, 1.5));', v: 'normalizar unitario direccion', i: 'gfx-trazado' },
{ t: 'reflect', g: 'geom', s: 'genType reflect(genType I, genType N)',
  d: 'Refleja la dirección $I$ en una superficie de normal $N$: $I - 2(N\\cdot I)\\,N$. <strong>$N$ tiene que ser unitaria</strong>. $I$ apunta hacia la superficie, como un rayo que llega.',
  e: 'vec3 rebote = reflect(rd, n);', v: 'reflejar reflexion espejo rebote', i: 'gfx-trazado' },
{ t: 'refract', g: 'geom', s: 'genType refract(genType I, genType N, float eta)',
  d: 'Desvía la dirección $I$ al atravesar una superficie de normal $N$; <code>eta</code> es el cociente de índices de refracción, 1/1,33 al entrar en el agua. Si hay reflexión total devuelve el vector cero. $I$ y $N$ tienen que ser unitarios.',
  e: 'vec3 dentro = refract(rd, n, 1.0 / 1.33);', v: 'refraccion snell agua vidrio' },
{ t: 'faceforward', g: 'geom', s: 'genType faceforward(genType N, genType I, genType Nref)',
  d: 'Devuelve $N$ o $-N$ para que mire en contra de $I$: $N$ si <code>dot(Nref, I) &lt; 0</code>, y $-N$ si no. Sirve para que la normal de una superficie vista por detrás siga apuntando hacia el ojo.',
  e: 'vec3 hacia = faceforward(n, rd, n);', v: 'orientar normal cara' },

/* ---------------- matrices ---------------- */
{ t: 'm * v · v * m · m * n', g: 'matriz', s: 'mat2 * vec2   // transforma\nvec2 * mat2   // traspuesta\nmat2 * mat2   // compone',
  d: 'Con matrices, <code>*</code> es el producto del álgebra lineal. <code>m * v</code> transforma el vector y <code>m * n</code> compone: primero se aplica <code>n</code> y después <code>m</code>. <code>v * m</code> equivale a multiplicar por la traspuesta, que en un giro es el giro contrario.',
  e: 'm = mat2(0.0, 1.0, -1.0, 0.0);\nvec2 ida = m * p;     // gira\nvec2 vuelta = p * m;  // gira al reves', v: 'producto matricial componer transformacion traspuesta', i: 'gfx-matrices' },
{ t: 'matrixCompMult', g: 'matriz', s: 'mat2 matrixCompMult(mat2 a, mat2 b)',
  d: 'Multiplica dos matrices <strong>elemento a elemento</strong>, no con el producto del álgebra lineal, que es <code>*</code>. Se usa muy poco.',
  e: 'mat2 elem = matrixCompMult(m, mat2(2.0));', v: 'producto elemento a elemento hadamard' },
{ t: 'inverse · transpose · determinant', g: 'matriz', s: '// no existen en WebGL 1',
  d: 'No existen en WebGL 1: llegaron con GLSL ES 3.00. Para un giro, la inversa es la traspuesta, y se consigue multiplicando por el otro lado, <code>v * m</code>. Para una 2×2 cualquiera, el determinante se escribe a mano.',
  e: 'float det = m[0][0] * m[1][1] - m[1][0] * m[0][1];', v: 'inversa traspuesta determinante' },

/* ---------------- comparar vectores ---------------- */
{ t: 'lessThan · lessThanEqual · greaterThan · greaterThanEqual', g: 'logica', s: 'bvec3 lessThan(vec3 a, vec3 b)',
  d: 'Comparan dos vectores componente a componente y devuelven un <code>bvec</code>. Para comparar dos escalares basta con <code>&lt;</code> y compañía.',
  e: 'bvec3 menores = lessThan(col, vec3(0.5));', v: 'menor mayor comparar componente' },
{ t: 'equal · notEqual', g: 'logica', s: 'bvec3 equal(vec3 a, vec3 b)',
  d: 'Igualdad componente a componente, con resultado <code>bvec</code>. Con floats la igualdad exacta casi nunca es buena idea: mejor <code>abs(a - b) &lt; 0.001</code>.',
  e: 'bvec2 iguales = equal(floor(p), vec2(0.0));', v: 'igual distinto' },
{ t: 'any · all · not', g: 'logica', s: 'bool any(bvec3 b)\nbool all(bvec3 b)\nbvec3 not(bvec3 b)',
  d: '<code>any</code> es cierto si alguna componente lo es; <code>all</code>, si lo son todas; <code>not</code> invierte cada una. Resumen una comparación de vectores en un solo <code>bool</code>.',
  e: 'bool fuera = any(greaterThan(abs(p), vec2(1.0)));', v: 'alguno todos negar' },

/* ---------------- texturas ---------------- */
{ t: 'texture2D', g: 'textura', s: 'vec4 texture2D(sampler2D tex, vec2 uv)\nvec4 texture2D(sampler2D tex, vec2 uv, float sesgo)',
  d: 'Lee una textura en las coordenadas <code>uv</code>, que van de 0 a 1 de un borde al otro, no en píxeles. Entre píxeles de la textura interpola. En los visores con memoria, <code>texture2D(iChannel0, fragCoord / iResolution.xy)</code> es el fotograma anterior en este mismo píxel. Es el nombre de WebGL 1: el <code>texture</code> de GLSL ES 3.00 aquí no compila.',
  e: 'vec3 previo = texture2D(iChannel0, fragCoord / iResolution.xy).rgb;', v: 'textura leer imagen muestrear texture sampler', i: 'gfx-buffers' },
{ t: 'textureCube', g: 'textura', s: 'vec4 textureCube(samplerCube tex, vec3 dir)',
  d: 'Lee una textura de cubo en la dirección <code>dir</code>, que no hace falta normalizar. Es la forma de poner cielos y reflejos precalculados.',
  v: 'cubo cielo reflejo entorno' },

/* ---------------- derivadas ---------------- */
{ t: 'dFdx · dFdy', g: 'deriv', s: 'genType dFdx(genType x)\ngenType dFdy(genType x)',
  d: 'Cuánto cambia una expresión de un píxel al de al lado, en horizontal y en vertical: una derivada por diferencias. La tarjeta gráfica procesa los píxeles en grupos de 2×2 y la calcula restando vecinos. En WebGL 1 necesitan la extensión <code>GL_OES_standard_derivatives</code>, que el preámbulo del curso ya activa.',
  e: 'vec3 rel = normalize(vec3(-dFdx(h), -dFdy(h), 0.01));', v: 'derivada diferencia pixel vecino relieve', i: 'gfx-derivadas' },
{ t: 'fwidth', g: 'deriv', s: 'genType fwidth(genType x)',
  d: '<code>abs(dFdx(x)) + abs(dFdy(x))</code>: cuánto cambia <code>x</code> en un píxel, en cualquier dirección. Usado como anchura de un <code>smoothstep</code> da un borde de un píxel a cualquier zoom.',
  e: 'float w = fwidth(d);\nfloat borde = 1.0 - smoothstep(-w, w, d);', v: 'antialiasing ancho de pixel suavizado', i: 'gfx-derivadas' },

/* ---------------- variables integradas ---------------- */
{ t: 'gl_FragCoord', g: 'integradas', s: 'vec4 gl_FragCoord',
  d: 'La posición del píxel en la ventana, en píxeles, con el origen <strong>abajo a la izquierda</strong> y el centro de cada píxel en .5: el primero es (0.5, 0.5). En el curso llega a <code>mainImage</code> como <code>fragCoord</code>.',
  e: 'vec2 pix = gl_FragCoord.xy;', v: 'coordenada pixel posicion ventana', i: 'gfx-pixel' },
{ t: 'gl_FragColor', g: 'integradas', s: 'vec4 gl_FragColor',
  d: 'La salida de color del fragment shader en WebGL 1. En el curso no se escribe directamente: <code>mainImage</code> rellena <code>color</code> y el cierre del visor lo copia en <code>gl_FragColor</code>.',
  v: 'salida color fragmento' },
{ t: 'gl_Position · gl_PointSize', g: 'integradas', s: 'vec4 gl_Position    // vertex shader\nfloat gl_PointSize  // vertex shader',
  d: 'Salidas del <em>vertex shader</em>: la posición del vértice y el tamaño de un punto. No existen en el fragment shader. En el visor del curso el vértice es fijo y el alumno no lo escribe.',
  v: 'vertice posicion punto tamano' },
{ t: 'gl_PointCoord', g: 'integradas', s: 'vec2 gl_PointCoord',
  d: 'Al pintar puntos como pequeños cuadrados, la posición del píxel dentro del cuadrado, de 0 a 1. El visor del curso no pinta puntos, así que aquí no se usa.',
  v: 'punto sprite particula' },
{ t: 'gl_FrontFacing', g: 'integradas', s: 'bool gl_FrontFacing',
  d: 'Vale <code>true</code> si el triángulo que se está pintando mira hacia la cámara. Con el triángulo fijo del visor vale siempre lo mismo.',
  v: 'cara frontal trasera' },

/* ---------------- preprocesador ---------------- */
{ t: '#define', g: 'preproc', s: '#define NOMBRE valor\n#define F(x) (expresion)',
  d: 'Sustituye texto antes de compilar, como en C. El preámbulo del curso define <code>PI</code> y <code>TAU</code>. Las macros con argumentos no son funciones: conviene poner paréntesis alrededor de todo.',
  e: '#define AA 2\n#define CUAD(x) ((x) * (x))', x: 'global', v: 'define macro constante preprocesador' },
{ t: '#extension', g: 'preproc', s: '#extension NOMBRE : enable',
  d: 'Activa una extensión de GLSL, y tiene que ir antes de cualquier código. El preámbulo del curso activa <code>GL_OES_standard_derivatives</code> para poder usar <code>dFdx</code>, <code>dFdy</code> y <code>fwidth</code>.',
  v: 'extension habilitar derivadas' },
{ t: '#ifdef · #else · #endif', g: 'preproc', s: '#ifdef NOMBRE\n...\n#else\n...\n#endif',
  d: 'Compilación condicional: lo que hay entre <code>#ifdef</code> y <code>#endif</code> solo se compila si el nombre está definido. Permite tener dos versiones de un shader en el mismo texto, por ejemplo una rápida y otra con más calidad.',
  e: '#define CALIDAD_ALTA\n#ifdef CALIDAD_ALTA\nconst int PASOS_R = 128;\n#else\nconst int PASOS_R = 48;\n#endif', x: 'global', v: 'if ifdef endif condicional compilacion' },

/* ---------------- el visor del curso ---------------- */
{ t: 'mainImage', g: 'visor', s: 'void mainImage(out vec4 color, in vec2 fragCoord)',
  d: 'La función que se escribe en cada visor: se llama una vez por píxel, con su posición en <code>fragCoord</code>, y tiene que dejar el color en <code>color</code>. Es la firma de Shadertoy, así que lo que se escribe en el curso funciona allí, y al revés.',
  e: 'void mainImage(out vec4 color, in vec2 fragCoord)\n{\n    vec2 uv = fragCoord / iResolution.xy;\n    color = vec4(uv, 0.0, 1.0);\n}', x: 'solo', v: 'funcion principal entrada shadertoy', i: 'gfx-pixel' },
{ t: 'fragCoord', g: 'visor', s: 'in vec2 fragCoord',
  d: 'El centro del píxel que se está calculando, en píxeles: es <code>gl_FragCoord.xy</code>. Dividido por <code>iResolution.xy</code> da coordenadas de 0 a 1; centrado y dividido por la altura, coordenadas sin deformar.',
  e: 'vec2 centrada = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;', v: 'coordenada del pixel posicion', i: 'gfx-coordenadas' },
{ t: 'iResolution', g: 'visor', s: 'uniform vec3 iResolution',
  d: 'El tamaño del lienzo en píxeles: <code>.x</code> es el ancho y <code>.y</code> el alto; <code>.z</code> vale 1. En la pasada de simulación de un visor con memoria es el tamaño del estado, que puede ser menor que el del lienzo.',
  e: 'float aspecto = iResolution.x / iResolution.y;', v: 'resolucion tamano ancho alto lienzo', i: 'gfx-coordenadas' },
{ t: 'iTime', g: 'visor', s: 'uniform float iTime',
  d: 'Los segundos desde que arrancó el visor. Se congela con «Pausa» y vuelve a cero con «Volver al original». Todo lo que se mueve en un shader sin memoria es una función de <code>iTime</code>.',
  e: 'vec2 orbita = 0.3 * vec2(cos(iTime), sin(iTime));', v: 'tiempo segundos animacion reloj', i: 'gfx-tiempo' },
{ t: 'iMouse', g: 'visor', s: 'uniform vec4 iMouse',
  d: 'El ratón, en píxeles del lienzo: <code>.xy</code> es la posición mientras se pulsa o se arrastra, y <code>.zw</code> el punto del último clic. Antes del primer clic vale cero. En Shadertoy, además, el signo de <code>.zw</code> dice si el botón sigue pulsado; en el curso no.',
  e: 'vec2 raton = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;', v: 'raton puntero clic arrastrar', i: 'gfx-raton' },
{ t: 'iFrame', g: 'visor', s: 'uniform float iFrame',
  d: 'El número de fotograma, desde 0. En los visores con memoria se usa para sembrar el estado en el primer paso: <code>step(iFrame, 0.5)</code> vale 1 solo entonces. En el curso es un <code>float</code>; en Shadertoy es un <code>int</code>, y allí se escribe <code>float(iFrame)</code>.',
  e: 'vec4 estado = vec4(0.0);\nestado = mix(estado, vec4(1.0), step(iFrame, 0.5));', v: 'fotograma frame contador sembrar', i: 'gfx-buffers' },
{ t: 'iChannel0', g: 'visor', s: 'uniform sampler2D iChannel0',
  d: 'En un visor con memoria, el estado que pintó el propio shader en el fotograma anterior, que se lee con <code>texture2D</code>. En los demás visores está declarado pero vacío, para que se puedan pegar shaders de Shadertoy que lo nombran.',
  e: 'vec4 ant = texture2D(iChannel0, fragCoord / iResolution.xy);', v: 'canal textura memoria buffer anterior', i: 'gfx-buffers' },
{ t: 'iChannel1', g: 'visor', s: 'uniform sampler2D iChannel1',
  d: 'En los visores con imagen, la foto que pinta el propio curso o, si se pulsa «Usar la cámara», la imagen de la cámara, como en un espejo. Se lee con <code>texture2D</code>, con coordenadas de 0 a 1 y el origen abajo a la izquierda, igual que <code>fragCoord</code>. La imagen de la cámara no sale del ordenador: se procesa en la tarjeta gráfica y ahí se queda.',
  e: 'vec3 foto = texture2D(iChannel1, fragCoord / iResolution.xy).rgb;', v: 'imagen foto camara webcam canal textura filtro', i: 'gfx-filtros' },
{ t: 'iChannelResolution', g: 'visor', s: 'uniform vec3 iChannelResolution[4]',
  d: 'El tamaño en píxeles de la imagen de cada canal: <code>iChannelResolution[1].xy</code> es el de la foto o la cámara. Hace falta para no deformar la imagen cuando el lienzo tiene otra proporción, y para saber cuánto mide un píxel de la imagen al leer a sus vecinos.',
  e: 'vec2 paso = 1.0 / iChannelResolution[1].xy;   // un pixel de la imagen\nvec3 vecino = texture2D(iChannel1, uv + vec2(paso.x, 0.0)).rgb;', v: 'resolucion tamano de la imagen canal pixel textura', i: 'gfx-filtros' },
{ t: 'PI · TAU', g: 'visor', s: '#define PI  3.14159265359\n#define TAU 6.28318530718',
  d: 'Constantes que pone el preámbulo del curso: $\\pi$ y $\\tau = 2\\pi$, la vuelta completa. <strong>No son de GLSL</strong>: al llevar un shader a Shadertoy hay que definirlas.',
  e: 'float sector = TAU / 6.0;', v: 'pi tau constante vuelta' },

/* ---------------- recetas del curso ---------------- */
{ t: 'hash', g: 'recetas', s: 'float hash(vec2 p)',
  d: 'Un número «al azar» entre 0 y 1 que es siempre el mismo para el mismo <code>p</code>: azar reproducible. Mezcla las coordenadas con un producto escalar, pasa el resultado por un seno y se queda con los decimales de un número grande. <strong>No es de GLSL</strong>: es la receta que usan los temas.',
  e: 'float hash(vec2 p)\n{\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n}', x: 'global', v: 'aleatorio azar pseudoaleatorio random', i: 'gfx-ruido' },
{ t: 'hash2', g: 'recetas', s: 'vec2 hash2(vec2 p)',
  d: 'Como <code>hash</code>, pero devuelve dos números: un punto al azar dentro de cada celda. Es la semilla de los diagramas de Voronoi.',
  e: 'vec2 hash2(vec2 p)\n{\n    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));\n    return fract(sin(p) * 43758.5453);\n}', x: 'global', v: 'punto aleatorio semilla voronoi', i: 'gfx-voronoi' },
{ t: 'ruido', g: 'recetas', s: 'float ruido(vec2 p)',
  d: 'Ruido de valor: un número al azar en cada esquina de la rejilla y una interpolación suave entre ellos. Da manchas continuas, todas de un tamaño parecido. Usa <code>hash</code>.',
  e: 'float ruido(vec2 q)\n{\n    vec2 i = floor(q), f = fract(q);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),\n               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}', x: 'global', v: 'noise ruido de valor manchas', i: 'gfx-ruido' },
{ t: 'fbm', g: 'recetas', s: 'float fbm(vec2 p)',
  d: 'Ruido fractal: se suman varias capas de <code>ruido</code>, cada una al doble de frecuencia y a la mitad de amplitud. Da nubes, montañas y humo con detalle a todas las escalas.',
  e: 'float fbm(vec2 q)\n{\n    float s = 0.0, a = 0.5;\n    for (int k = 0; k < 5; k++) {\n        s += a * ruido(q);\n        q *= 2.0;\n        a *= 0.5;\n    }\n    return s;\n}', x: 'global', v: 'ruido fractal octavas movimiento browniano nubes', i: 'gfx-ruido' },
{ t: 'rot', g: 'recetas', s: 'mat2 rot(float a)',
  d: 'La matriz de giro de ángulo <code>a</code>, escrita por columnas. <code>rot(a) * p</code> gira el punto; si se aplica a las coordenadas antes de dibujar, la figura se ve girar en el sentido contrario.',
  e: 'mat2 rot(float a)\n{\n    float c = cos(a), s = sin(a);\n    return mat2(c, s, -s, c);\n}', x: 'global', v: 'rotacion giro matriz', i: 'gfx-matrices' },
{ t: 'sdSegmento', g: 'recetas', s: 'float sdSegmento(vec2 p, vec2 a, vec2 b)',
  d: 'La distancia de <code>p</code> al segmento de <code>a</code> a <code>b</code>: se proyecta sobre la recta, se recorta el parámetro a $[0, 1]$ y se mide. Restándole un grosor dibuja trazos con las puntas redondas.',
  e: 'float sdSegmento(vec2 p, vec2 a, vec2 b)\n{\n    vec2 pa = p - a, ba = b - a;\n    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n    return length(pa - ba * h);\n}', x: 'global', v: 'distancia segmento trazo linea', i: 'gfx-curvas' },
{ t: 'sdEsfera · sdCaja', g: 'recetas', s: 'float sdEsfera(vec3 p, float r)\nfloat sdCaja(vec3 p, vec3 b)',
  d: 'Distancias con signo a una esfera de radio <code>r</code> y a una caja de semilados <code>b</code>, las dos centradas en el origen. Negativas dentro, positivas fuera y cero en la superficie. La de la caja sirve igual en 2D con <code>vec2</code>.',
  e: 'float sdEsfera(vec3 p, float r)\n{\n    return length(p) - r;\n}\nfloat sdCaja(vec3 p, vec3 b)\n{\n    vec3 q = abs(p) - b;\n    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}', x: 'global', v: 'esfera caja cubo sdf distancia con signo', i: 'gfx-escena' },
{ t: 'smin', g: 'recetas', s: 'float smin(float a, float b, float k)',
  d: 'Mínimo suave: une dos distancias redondeando la zona donde se encuentran, con un radio de fusión <code>k</code>. Funde dos cuerpos como dos gotas de mercurio.',
  e: 'float smin(float a, float b, float k)\n{\n    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n    return mix(b, a, h) - k * h * (1.0 - h);\n}', x: 'global', v: 'union suave fusion minimo suave', i: 'gfx-escena' },
{ t: 'mapa · normal', g: 'recetas', s: 'float mapa(vec3 p)\nvec3 normal(vec3 p)',
  d: 'En los temas de 3D, <code>mapa(p)</code> es la distancia con signo de <code>p</code> a toda la escena, y <code>normal(p)</code> la deriva por diferencias en los tres ejes: el gradiente de la distancia es perpendicular a la superficie.',
  e: 'vec3 normal(vec3 p)\n{\n    vec2 e = vec2(0.002, 0.0);\n    return normalize(vec3(mapa(p + e.xyy) - mapa(p - e.xyy),\n                          mapa(p + e.yxy) - mapa(p - e.yxy),\n                          mapa(p + e.yyx) - mapa(p - e.yyx)));\n}', x: 'global', v: 'escena sdf gradiente normal superficie', i: 'gfx-raymarching' },
{ t: 'paleta', g: 'recetas', s: 'vec3 paleta(float t, vec3 a, vec3 b, vec3 f, vec3 d)',
  d: 'La paleta de cosenos de Íñigo Quílez: cada canal es un coseno con su propia fase. Con cuatro vectores salen arcoíris, fuegos o degradados de dos colores.',
  e: 'vec3 paleta(float t, vec3 a, vec3 b, vec3 f, vec3 d)\n{\n    return a + b * cos(TAU * (f * t + d));\n}', x: 'global', v: 'paleta coseno color quilez degradado', i: 'gfx-color' },
{ t: 'hsv2rgb', g: 'recetas', s: 'vec3 hsv2rgb(vec3 c)',
  d: 'Pasa de tono, saturación y brillo, los tres entre 0 y 1, a RGB sin ramas: el tono es un ángulo repartido en seis sectores.',
  e: 'vec3 hsv2rgb(vec3 c)\n{\n    vec3 k = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);\n    return c.z * mix(vec3(1.0), k, c.y);\n}', x: 'global', v: 'hsv tono saturacion brillo', i: 'gfx-color' },

/* ---------------- lo que no hay en WebGL 1 ---------------- */
{ t: 'round · trunc', g: 'es3', s: '// no existen en WebGL 1',
  d: 'No existen en WebGL 1. Redondear al entero más cercano es <code>floor(x + 0.5)</code>; truncar hacia cero, <code>sign(x) * floor(abs(x))</code>.',
  e: 'float redondeado = floor(x + 0.5);\nfloat truncado = sign(x) * floor(abs(x));', v: 'redondear truncar roundeven' },
{ t: '% · & · | · ^ · << · >>', g: 'es3', s: '// reservados en WebGL 1',
  d: 'El resto entero y los operadores de bits están reservados en GLSL ES 1.00 y no compilan en WebGL 1. El resto se calcula con <code>mod</code> en floats, y el bit número $k$ de un entero guardado en un float, con <code>mod(floor(n / pow(2.0, k)), 2.0)</code>.',
  e: 'float codigo = 13.0;   // 1101 en binario\nfloat bit2 = mod(floor(codigo / pow(2.0, 2.0)), 2.0);   // 1.0', v: 'resto modulo bits bitwise desplazamiento and or xor binario' },
{ t: 'texture', g: 'es3', s: '// GLSL ES 3.00; en WebGL 1: texture2D',
  d: 'En GLSL ES 3.00, que es lo que usan WebGL 2 y muchos ejemplos modernos de Shadertoy, la lectura de texturas se llama <code>texture</code>. En WebGL 1 se llama <code>texture2D</code> o <code>textureCube</code>, y es lo que hay que escribir en el curso.',
  v: 'textura leer webgl2' },
{ t: 'float[3](…)', g: 'es3', s: 'float a[3] = float[3](1.0, 2.0, 3.0);   // no compila',
  d: 'Inicializar un array al declararlo es de GLSL ES 3.00. En WebGL 1 un array se declara y se rellena elemento a elemento, y no se puede escribir un array <code>const</code>.',
  v: 'array inicializador lista constante arrays' },
{ t: 'switch · uint', g: 'es3', s: '// reservados en WebGL 1',
  d: '<code>switch</code> con sus <code>case</code> y el tipo entero sin signo <code>uint</code> son de GLSL ES 3.00; en WebGL 1 no compilan. Un <code>switch</code> se sustituye por una cadena de <code>if</code>.',
  v: 'switch case uint sin signo' },
{ t: 'isnan · isinf', g: 'es3', s: '// no existen en WebGL 1',
  d: 'No existen en WebGL 1, y no hay una forma fiable de detectar un valor inválido. Lo que se hace es evitarlo en origen: <code>clamp</code> antes de <code>acos</code>, <code>max(x, 0.0)</code> antes de <code>sqrt</code>, y nunca dividir por algo que pueda valer cero.',
  e: 'float seguro = sqrt(max(x, 0.0));', v: 'nan infinito invalido' }
]
};
